package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="video_analyses", indexes={@Index(name="idx_video_analysis_asset", columnList="video_asset_id"),@Index(name="idx_video_analysis_status", columnList="status")})
public class VideoAnalysis { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="video_asset_id") @JsonIgnore private VideoAsset videoAsset; @Enumerated(EnumType.STRING) private VideoAnalysisStatus status=VideoAnalysisStatus.PENDING; private Integer detectedEvents=0; @Column(length=1000) private String heatmapUrl; @Column(length=1000) private String highlightUrl; private Double analysisScore=0.0; private LocalDateTime completedAt; public boolean isCompleted(){return status==VideoAnalysisStatus.COMPLETED;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public VideoAsset getVideoAsset(){return videoAsset;} public void setVideoAsset(VideoAsset videoAsset){this.videoAsset=videoAsset;} public VideoAnalysisStatus getStatus(){return status;} public void setStatus(VideoAnalysisStatus status){this.status=status;} public Integer getDetectedEvents(){return detectedEvents;} public void setDetectedEvents(Integer detectedEvents){this.detectedEvents=detectedEvents;} public String getHeatmapUrl(){return heatmapUrl;} public void setHeatmapUrl(String heatmapUrl){this.heatmapUrl=heatmapUrl;} public String getHighlightUrl(){return highlightUrl;} public void setHighlightUrl(String highlightUrl){this.highlightUrl=highlightUrl;} public Double getAnalysisScore(){return analysisScore;} public void setAnalysisScore(Double analysisScore){this.analysisScore=analysisScore;} public LocalDateTime getCompletedAt(){return completedAt;} public void setCompletedAt(LocalDateTime completedAt){this.completedAt=completedAt;} }
